sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.row {
  display: flex;
  flex-wrap: wrap;
  gap: 20px;
  margin-top: 20px;
}

.card {
  border: 1px solid #ddd;
  border-radius: 10px;
  overflow: hidden;
  transition: transform 0.3s, box-shadow 0.3s;
  width: 100%;
  max-width: 300px;
  margin: 0 auto;
}

.card:hover {
  transform: translateY(-5px);
  box-shadow: 0 8px 20px rgba(0,0,0,0.2);
}

.card-img-top {
  width: 100%;
  height: 150px;
  object-fit: cover;
}

.card-body {
  padding: 15px;
}

.card-title {
  font-size: 1.2rem;
  font-weight: bold;
  margin-bottom: 10px;
}

.card-text {
  font-size: 0.95rem;
  color: #555;
  height: 40px;
  overflow: hidden;
}

.btn-primary {
  background-color: #168AFF;
  border: none;
  border-radius: 5px;
  padding: 8px 15px;
  text-decoration: none;
  color: #fff;
  font-weight: 500;
  transition: background-color 0.3s;
}

.btn-primary:hover {
  background-color: #0f6acc;
}

sp_widget.script:
(function() {
  data.catalogs = [];

  var gr = new GlideRecord("sc_catalog");
  gr.addQuery("title", "Office Services"); // Filter by catalog name
  gr.query();
  while (gr.next()) {
    data.catalogs.push({
      sys_id: gr.getUniqueValue(),
      name: gr.getValue("title"),
      description: gr.getValue("description"),
      image: gr.getValue("icon"),
      url: "?id=sc_category&sys_id=" + gr.getUniqueValue()
    });
  }
})();
